1	/// The chain's width until its tab has been laid out: an icon tab is a square
2	/// a little wider than the icon it centres.
3	const CHAIN_WIDTH_ESTIMATE: Pixels = px(40.);
4	
5	/// How the tint and the chain's icon slide between tabs: critically damped,
6	/// so they settle without bouncing past.
7	const CHAIN_SPRING: SpringConfig = SpringConfig::new(400., 40., 1.);
8	
9	/// How strongly the selected tabs and their body are tinted: red for Code,
10	/// blue for Spec, purple for both, green for Ask, and grey for Freeform.
11	const TINT_OPACITY: f32 = 0.1;
12	
13	/// The hues the tabs are tinted with: the theme's, or those chosen in the
14	/// theme editor in their place.
15	#[derive(Clone, Copy)]
16	struct Hues {
17	    red: Hsla,
18	    /// The chain's, midway between Code's red and Spec's blue unless chosen.
19	    purple: Hsla,
20	    blue: Hsla,
21	    green: Hsla,
22	    /// The theme's tertiary grey, for Freeform.
23	    grey: Hsla,
24	}
25	
26	impl Hues {
27	    fn of(cx: &App) -> Self {
28	        let theme = cx.theme();
29	        let chosen = crate::theme::mode_colors(theme.is_dark());
30	        let pick = |chosen: Option<u32>, own: Hsla| chosen.map_or(own, crate::theme::color);
31	        let (red, blue) = (pick(chosen.code, theme.red), pick(chosen.spec, theme.blue));
32	        Self {
33	            red,
34	            purple: pick(chosen.chain, midway(red, blue)),
35	            blue,
36	            green: pick(chosen.ask, theme.green),
37	            grey: crate::theme::Hue::Grey.of(crate::theme::palette(cx)),
38	        }
39	    }
40	}
41	
42	/// The colour midway between `code` and `spec`, the shorter way round the
43	/// hue circle, at full strength: the chain's own colour.
44	pub fn midway(code: Hsla, spec: Hsla) -> Hsla {
45	    Hsla {
46	        a: 1.,
47	        ..blend(code, spec, 0.5)
48	    }
49	}
50	
51	/// The tint at `position` between the tabs: red at Code (0), the chain's
52	/// purple (1), blue at Spec (2), green at Ask (3), and grey at Freeform (4).
53	/// The tabs wrap around, so past Freeform it blends straight back to Code's
54	/// red at 5.
55	fn tint(hues: Hues, position: f32) -> Hsla {
56	    let Hues {
57	        red,
58	        purple,
59	        blue,
60	        green,
61	        grey,
62	    } = hues;
63	    let position = position.rem_euclid(TABS.len() as f32);
64	    if position > 4. {
65	        blend(grey, red, position - 4.)
66	    } else if position > 3. {
67	        blend(green, grey, position - 3.)
68	    } else if position > 2. {
69	        blend(blue, green, position - 2.)
70	    } else if position > 1. {
71	        blend(purple, blue, position - 1.)
72	    } else {
73	        blend(red, purple, position)
74	    }
75	}
76	
77	/// The tint of the tab `mode` is sent from, as the chat input shows it.
78	pub fn mode_tint(mode: SendMode, cx: &App) -> Hsla {
79	    let position = TABS.iter().position(|tab| *tab == mode).unwrap_or(0);
80	    tint(Hues::of(cx), position as f32)
81	}
82	
83	/// The colour of `mode` at full strength, where [`mode_tint`] is only a
84	/// tint of it: for a mark, such as an icon, that stands for the mode.
85	pub fn mode_color(mode: SendMode, cx: &App) -> Hsla {
86	    Hsla {
87	        a: 1.,
88	        ..mode_tint(mode, cx)
89	    }
90	}
91	
92	/// The send button's colour: the selected tab's mode colour at full
93	/// strength, where the tab and body have only a tint of it.
94	fn send_color(position: f32, cx: &App) -> Hsla {
95	    Hsla {
96	        a: 1.,
97	        ..tint(Hues::of(cx), position)
98	    }
99	}
100	
101	/// How far the line between the send button's halves steps from its colour:
102	/// half as far as its hover, just enough to part them.
103	const SEND_SEAM_STEP: f32 = 0.03;
104	
105	/// `color` a step darker in dark mode, whose hues are light, and lighter in
106	/// light mode, for the send button's hover, press, and the line between its
107	/// halves.
108	fn send_step(color: Hsla, by: f32, cx: &App) -> Hsla {
109	    let by = if cx.theme().is_dark() { -by } else { by };
110	    Hsla {
111	        l: (color.l + by).clamp(0., 1.),
112	        ..color
113	    }
114	}
115	
116	/// The line between the send button's halves: faintly off its colour, and
117	/// faded with the chevron half while that is disabled, as gpui-kit fades a
118	/// disabled button's background, so it never stands out from a faded button.
119	fn send_seam(position: f32, disabled: bool, cx: &App) -> Hsla {
120	    let seam = send_step(send_color(position, cx), SEND_SEAM_STEP, cx);
121	    if disabled {
122	        seam.opacity(DISABLED_OPACITY)
123	    } else {
124	        seam
125	    }
126	}
127	
128	/// How opaque gpui-kit draws a disabled custom button's colour.
129	const DISABLED_OPACITY: f32 = 0.15;
130	
131	/// The send button's colours, with text in the theme's colour for a solid
132	/// hue.
133	fn send_colors(position: f32, cx: &App) -> ButtonCustomVariant {
134	    let color = send_color(position, cx);
135	    ButtonCustomVariant::new(cx)
136	        .color(color)
137	        .foreground(cx.theme().danger_foreground)
138	        .hover(send_step(color, 0.06, cx))
139	        .active(send_step(color, 0.12, cx))
140	}
141	
142	/// `from` blended `t` of the way to `to`, at the tint's opacity.
143	fn blend(from: Hsla, to: Hsla, t: f32) -> Hsla {
144	    let t = t.clamp(0., 1.);
145	    // A grey has no hue of its own, so blending to or from one keeps the
146	    // other's hue, only fading its saturation, rather than passing through
147	    // whatever hue the grey happens to be given.
148	    const GREY: f32 = 0.05;
149	    let from_h = if from.s < GREY { to.h } else { from.h };
150	    let to_h = if to.s < GREY { from_h } else { to.h };
151	    let from = Hsla { h: from_h, ..from };
152	    let to = Hsla { h: to_h, ..to };
153	    // The shorter way round the hue circle, which from red to blue passes
154	    // through purple rather than green.
155	    let hue_step = (to.h - from.h + 0.5).rem_euclid(1.) - 0.5;
156	    Hsla {
157	        h: (from.h + hue_step * t).rem_euclid(1.),
158	        s: from.s + (to.s - from.s) * t,
159	        l: from.l + (to.l - from.l) * t,
160	        a: TINT_OPACITY,
161	    }
162	}
163	
164	/// How much of tab `ix`'s tint shows with the tint at `position`: all of it
165	/// while the tab is selected, alone or (for Code and Spec) with the other,
166	/// fading out over one tab either side.
167	fn tab_tint_shown(ix: usize, position: f32) -> f32 {
168	    let (first, last) = match TABS[ix] {
169	        SendMode::Code => (0., 1.),
170	        SendMode::Spec => (1., 2.),
171	        SendMode::Both | SendMode::Ask | SendMode::Freeform => (ix as f32, ix as f32),
172	    };
173	    // The tabs wrap around, so Code is as near Freeform as Chain is to Code.
174	    let count = TABS.len() as f32;
175	    let position = position.rem_euclid(count);
176	    let distance = [position - count, position, position + count]
177	        .into_iter()
178	        .map(|position| (first - position).max(position - last).max(0.))
179	        .fold(f32::MAX, f32::min);
180	    (1. - distance).clamp(0., 1.)
181	}
