183	/// What a prompt is sent to work on: the selected tab.
184	#[derive(Clone, Copy, Debug, PartialEq)]
185	pub enum SendMode {
186	    Code,
187	    /// The code and the spec together.
188	    Both,
189	    Spec,
190	    /// A question, which edits neither the code nor the spec.
191	    Ask,
192	    /// The prompt passed to the agent just as it is written: no system
193	    /// prompt, hidden anchor, spec build, or slices.
194	    Freeform,
195	}
196	
197	    fn render(&mut self, window: &mut Window, cx: &mut Context<Self>) -> impl IntoElement {
198	        let text = self.editor.read(cx).value();
199	        let (height, one_row) = self.fit.heights(&self.editor, window, cx);
200	        let empty = text.is_empty();
201	        // A question is asked straight away, beside whatever the harness is
202	        // working on, so it never queues.
203	        let queues = self.busy && TABS[self.selected_tab] != SendMode::Ask;
204	
205	        // Follows how the editor is laid out, to fit it anew.
206	        let track_layout =
207	            GrowToFit::tracker(&self.editor, cx.entity().downgrade(), |this: &mut Self| {
208	                &mut this.fit
209	            });
210	
211	        // Code, the chain, Spec, Ask, and Freeform are tabs side by side, each its own
212	        // bar so that selecting the chain can show Code and Spec selected
213	        // along with it, as one locked tab. The chain shows an icon: broken
214	        // and dimmed until selected, then joined. Selecting it pulls in half
215	        // its width from either side, as though by negative margins, so Code
216	        // and Spec slide together until they meet beneath it and it sits on
217	        // the seam between them.
218	        let selected = self.selected_tab;
219	        let unified = selected == BOTH_TAB;
220	        let chain_width = self.chain_width.unwrap_or(CHAIN_WIDTH_ESTIMATE);
221	        let join = SpringAnimation::new(CHAIN_SPRING).to(if unified { 1. } else { 0. });
222	        // The tint slides between the tabs, so going from Code to Spec passes
223	        // through purple. Its position is the selected tab's index: 0 for
224	        // Code, 1 for the chain, 2 for Spec, 3 for Ask, 4 for Freeform.
225	        let tint_slide = SpringAnimation::new(CHAIN_SPRING).to(self.tint_target);
226	        let hues = Hues::of(cx);
227	        let tint = move |position| tint(hues, position);
228	        // A joined chain once selected, and a broken one dimmed to half
229	        // opacity until then.
230	        let chain_icon = Icon::new(if unified {
231	            IconName::Link
232	        } else {
233	            IconName::Unlink
234	        })
235	        .text_color(if unified {
236	            cx.theme().tab_active_foreground
237	        } else {
238	            cx.theme().tab_foreground.opacity(0.5)
239	        });
240	        // A tab's contents: its label, or the chain's icon. An icon tab is a
241	        // small square with none of a label's padding, so no room has to be
242	        // made for the chain: it sits between Code and Spec the way any two
243	        // tabs sit side by side.
244	        let tab = |ix: usize| match TABS[ix] {
245	            SendMode::Both => Tab::new()
246	                .icon(chain_icon.clone())
247	                .tooltip(|window, cx| Tooltip::new(SendMode::Both.label()).build(window, cx)),
248	            mode => Tab::new().label(mode.label()),
249	        };
250	        // A tint laid over a tab, as wide as the tab itself (an invisible copy
251	        // of it) rather than its bar, fading out as the tab is deselected.
252	        let tab_tint = |ix: usize| {
253	            let tint_slide = tint_slide.clone();
254	            div()
255	                .absolute()
256	                .top_0()
257	                .bottom_0()
258	                .left_0()
259	                .flex()
260	                .child(
261	                    TabBar::new(("tint-width", ix))
262	                        .selected_index(0)
263	                        .child(Tab::new().label(TABS[ix].label()))
264	                        .invisible(),
265	                )
266	                .with_spring(("tab-tint", ix), tint_slide, move |this, position| {
267	                    let shown = tab_tint_shown(ix, position);
268	                    let color = tint(position);
269	                    this.bg(Hsla {
270	                        a: color.a * shown,
271	                        ..color
272	                    })
273	                })
274	        };
275	        let chat_input = cx.entity().downgrade();
276	        let full_tab = |ix: usize| {
277	            let chat_input = chat_input.clone();
278	            let bar = TabBar::new(TABS[ix].id())
279	                .on_click(move |_, window, cx| {
280	                    chat_input
281	                        .update(cx, |this, cx| this.select_tab(ix, window, cx))
282	                        .ok();
283	                })
284	                .child(tab(ix));
285	            // The chain itself never shows as selected: once joined it sits
286	            // over Code and Spec, whose selection shows through around its icon.
287	            if ix != BOTH_TAB
288	                && (selected == ix
289	                    || (unified && matches!(TABS[ix], SendMode::Code | SendMode::Spec)))
290	            {
291	                bar.selected_index(0)
292	            } else {
293	                bar
294	            }
295	        };
296	        let measure_chain = {
297	            let chat_input = chat_input.clone();
298	            canvas(
299	                |_, _, _| {},
300	                move |bounds, _, _, cx| {
